import '../../runtime/dc-core-bare/prelude.dart';

@bare
u64 sumTo(u64 n) {
  var i = u64(0);
  var total = u64(0);
  while (i < n) {
    total = total + i;
    i = i + u64(1);
  }
  return total;
}

@bare
u64 firstAtLeast(u64 n, u64 threshold) {
  var i = u64(0);
  var total = u64(0);
  while (i < n) {
    total = total + i;
    if (threshold < total) {
      return i;
    }
    i = i + u64(1);
  }
  return i;
}

import '../../runtime/dc-core-bare/prelude.dart';

class StepCounter extends HeapObject {
  u64 total;
  StepCounter(this.total);
}

@bare
u64 collatzSteps(u64 start) {
  var n = start;
  var steps = u64(0);
  while (u64(1) < n) {
    if ((n & u64(1)) < u64(1)) {
      n = n >> u64(1); // even
    } else {
      n = n + n + n + u64(1); // odd: 3n + 1
    }
    steps = steps + u64(1);
  }
  return steps;
}

@bare
u64 sumCollatzSteps(u64 upTo) {
  var counter = StepCounter(u64(0));
  var i = u64(1);
  while (i < upTo + u64(1)) {
    counter.total = counter.total + collatzSteps(i);
    i = i + u64(1);
  }
  return counter.total;
}

import '../../runtime/dc-core-bare/prelude.dart';

class Box extends HeapObject {
  final u64 value;
  const Box(this.value);
}

@bare
u64 sumBoxValues(u64 n) {
  if (n < u64(1)) {
    return u64(0);
  }
  final b = Box(n);
  final v = b.value;
  return v + sumBoxValues(n - u64(1));
}

