@bare
u64 gcd(u64 x, u64 y) {
  var a = x;
  var b = y;
  while (u64(0) < b) {
    var t = a % b;
    a = b;
    b = t;
  }
  return a;
}

@bare
u32 gcdU32(u32 x, u32 y) {
  var a = x;
  var b = y;
  while (u32(0) < b) {
    var t = a % b;
    a = b;
    b = t;
  }
  return a;
}

@bare
u64 digitSum(u64 n) {
  var rest = n;
  var sum = u64(0);
  while (u64(0) < rest) {
    sum = sum + rest % u64(10);
    rest = rest ~/ u64(10);
  }
  return sum;
}

@bare
u64 isPrime(u64 n) {
  if (n < u64(2)) {
    return u64(0);
  }
  var i = u64(2);
  while (i * i <= n) {
    if (n % i == u64(0)) {
      return u64(0);
    }
    i = i + u64(1);
  }
  return u64(1);
}

@bare
u64 powMod(u64 base, u64 exp, u64 m) {
  var b = base % m;
  var e = exp;
  var acc = u64(1) % m;
  while (u64(0) < e) {
    if (e % u64(2) == u64(1)) {
      acc = acc * b % m;
    }
    b = b * b % m;
    e = e ~/ u64(2);
  }
  return acc;
}

@bare
u64 lcm(u64 a, u64 b) {
  if (a == u64(0)) {
    return u64(0);
  }
  if (b == u64(0)) {
    return u64(0);
  }
  return a ~/ gcd(a, b) * b;
}

@bare
u64 sumProperDivisors(u64 n) {
  var sum = u64(0);
  var i = u64(1);
  while (i < n) {
    if (n % i == u64(0)) {
      sum = sum + i;
    }
    i = i + u64(1);
  }
  return sum;
}

