@bare
f64 horner4(f64 x) {
  var acc = f64(1.0) / f64(24.0);
  acc = acc * x + f64(1.0) / f64(6.0);
  acc = acc * x + f64(0.5);
  acc = acc * x + f64(1.0);
  acc = acc * x + f64(1.0);
  return acc;
}

@bare
f64 geomSum(u64 n, f64 ratio) {
  var sum = f64(0.0);
  var term = f64(1.0);
  var i = u64(0);
  while (i < n) {
    sum = sum + term;
    term = term * ratio;
    i = i + u64(1);
  }
  return sum;
}
